// ***************
// Filename: spi_top.sv
// Author: FPGA Cores 4 U
// Description: spi_master with its AXI4-Lite register interface, the block
//   designs and testbenches instantiate: the register map spi_master_regs
//   (u_regs, src/include/spi_master_regs.sv, ID "SPIM", VERSION and DATE at
//   0x00-0x08, the registers from 0x10) and the logic spi_master (u_core,
//   src/spi_master.sv), joined by the register interface spi_master_regs_if
//   (u_regs_if). Generated by ip/scripts/regmap_gen.py from
//   spi_master_regs.json and the ports of spi_master: regenerate after
//   changing either. Clock - aclk. Reset - synchronous active low aresetn.
// Date: 2026-10-20
module spi_top #(
  parameter int CLK_HZ = 100_000_000,
  parameter int SCLK_HZ = 1_000_000,
  parameter int DATA_W = 32,
  parameter int NUM_CS = 4,
  parameter int FIFO_DEPTH = 512
) (
  input  logic aclk,
  input  logic aresetn,
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 8
  axil_if.slave s_axil,
  // s_axis: axis_if.slave (ip/shared/src/interfaces/axis_if.sv), DATA_W = DATA_W
  axis_if.slave s_axis,
  // m_axis: axis_if.master (ip/shared/src/interfaces/axis_if.sv), DATA_W = DATA_W
  axis_if.master m_axis,
  // spi: spi_if.master (ip/shared/src/interfaces/spi_if.sv), NUM_CS = NUM_CS {spi_sclk_o=sclk spi_mosi_o=mosi spi_miso_i=miso spi_cs_n_o=cs_n}
  spi_if.master spi
);
  // register interface between the register map and the logic
  spi_master_regs_if u_regs_if ();

  spi_master_regs #(
    .DIV_RST((CLK_HZ / (2 * SCLK_HZ)) - 1)
  ) u_regs (
    .aclk,
    .aresetn,
    .s_axil(s_axil),
    .r(u_regs_if)
  );
  spi_master #(
    .CLK_HZ(CLK_HZ),
    .SCLK_HZ(SCLK_HZ),
    .DATA_W(DATA_W),
    .NUM_CS(NUM_CS),
    .FIFO_DEPTH(FIFO_DEPTH)
  ) u_core (
    .aclk,
    .aresetn,
    .s_axis,
    .m_axis,
    .spi,
    .regs(u_regs_if)
  );
endmodule
